import json
import os
from typing import Any, Dict, List, Optional

import requests


VENDOR_API_HOST = "https://api.veryfi.com"


def _auth_headers() -> Dict[str, str]:
    client_id = os.environ.get("VERYFI_CLIENT_ID", "")
    username = os.environ.get("VERYFI_USERNAME", "")
    api_key = os.environ.get("VERYFI_API_KEY", "")
    if not client_id or not username or not api_key:
        raise ValueError("VERYFI_CLIENT_ID, VERYFI_USERNAME, and VERYFI_API_KEY are required")
    return {
        "CLIENT-ID": client_id,
        "AUTHORIZATION": f"apikey {username}:{api_key}",
    }


def _normalize_line_items(items: Any) -> List[Dict[str, Any]]:
    if not isinstance(items, list):
        return []
    normalized = []
    for item in items:
        if isinstance(item, dict):
            normalized.append(
                {
                    "description": item.get("description") or item.get("name") or item.get("item"),
                    "quantity": item.get("quantity"),
                    "unit_price": item.get("unit_price") or item.get("price"),
                    "amount": item.get("total") or item.get("amount") or item.get("line_total"),
                }
            )
    return normalized


def extract_invoice_fields(invoice_file_path: str) -> Dict[str, Any]:
    url = f"{VENDOR_API_HOST}/api/v8/partner/documents"
    with open(invoice_file_path, "rb") as f:
        response = requests.post(
            url,
            headers=_auth_headers(),
            files={"file": f},
            timeout=60,
        )
    response.raise_for_status()
    payload = response.json()
    vendor = payload.get("vendor") or {}
    date = payload.get("date") or payload.get("invoice_date")
    total = payload.get("total") or payload.get("amount") or payload.get("total_amount")
    line_items = _normalize_line_items(payload.get("line_items") or payload.get("items"))
    return {
        "vendor": vendor.get("name") if isinstance(vendor, dict) else vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
        "raw": payload,
    }


def main() -> None:
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument("invoice_file_path")
    args = parser.parse_args()
    print(json.dumps(extract_invoice_fields(args.invoice_file_path), indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()

import base64
import json
import os
import sys
from typing import Any, Dict, Optional

import requests


OPENAI_API_URL = "https://api.openai.com/v1/responses"
OPENAI_MODEL = "gpt-5.4-mini"


def _encode_input(data: bytes) -> str:
    return base64.b64encode(data).decode("utf-8")


def extract_receipt_fields(image_path: str) -> Dict[str, Any]:
    api_key = os.environ["OPENAI_API_KEY"]
    with open(image_path, "rb") as f:
        image_bytes = f.read()

    payload = {
        "model": OPENAI_MODEL,
        "input": [
            {
                "role": "user",
                "content": [
                    {
                        "type": "input_text",
                        "text": "Extract merchant, tax, total, and items from this receipt. Return strict JSON with keys merchant (string or null), tax (number or null), total (number or null), and items (array of objects with name, quantity, and price).",
                    },
                    {
                        "type": "input_image",
                        "image_url": f"data:image/png;base64,{_encode_input(image_bytes)}",
                    },
                ],
            }
        ],
        "text": {"format": {"type": "json_object"}},
    }

    response = requests.post(
        OPENAI_API_URL,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        data=json.dumps(payload),
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()

    output_text: Optional[str] = None
    for item in data.get("output", []):
        for content in item.get("content", []):
            if content.get("type") in {"output_text", "text"}:
                output_text = content.get("text")
                if output_text:
                    break
        if output_text:
            break

    if not output_text:
        raise ValueError("No structured response content returned by OpenAI API")

    return json.loads(output_text)


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python extract_receipt_fields.py <receipt_image_path>")
    result = extract_receipt_fields(sys.argv[1])
    sys.stdout.write(json.dumps(result))


if __name__ == "__main__":
    main()

import json
import os
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, Optional

from openai import OpenAI


client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))


STANDARD_SCHEMA = {
    "type": "object",
    "properties": {
        "merchant_name": {"type": ["string", "null"]},
        "transaction_date": {"type": ["string", "null"]},
        "currency": {"type": ["string", "null"]},
        "total_amount": {"type": ["number", "null"]},
        "tip_amount": {"type": ["number", "null"]},
        "tax_amount": {"type": ["number", "null"]},
        "category": {"type": ["string", "null"]},
        "payment_method": {"type": ["string", "null"]},
        "receipt_id": {"type": ["string", "null"]},
        "confidence": {"type": ["number", "null"]},
    },
    "required": [
        "merchant_name",
        "transaction_date",
        "currency",
        "total_amount",
        "tip_amount",
        "tax_amount",
        "category",
        "payment_method",
        "receipt_id",
        "confidence",
    ],
    "additionalProperties": False,
}


def _to_decimal(value: Any) -> Optional[Decimal]:
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float, Decimal)):
        return Decimal(str(value))
    if isinstance(value, str):
        text = value.strip().replace(",", "")
        if not text:
            return None
        try:
            return Decimal(text)
        except InvalidOperation:
            return None
    return None


def _normalize_number(value: Any) -> Optional[float]:
    number = _to_decimal(value)
    return float(number) if number is not None else None


def _first_present(data: Dict[str, Any], keys: list[str]) -> Any:
    for key in keys:
        if key in data and data[key] not in (None, ""):
            return data[key]
    return None


def normalize_expense(extracted_fields: Dict[str, Any]) -> Dict[str, Any]:
    normalized = {
        "merchant_name": _first_present(extracted_fields, ["merchant_name", "merchant", "vendor", "store_name"]),
        "transaction_date": _first_present(extracted_fields, ["transaction_date", "date", "purchase_date"]),
        "currency": _first_present(extracted_fields, ["currency", "ccy"]),
        "total_amount": _normalize_number(_first_present(extracted_fields, ["total_amount", "amount", "total", "grand_total"])),
        "tip_amount": _normalize_number(_first_present(extracted_fields, ["tip_amount", "tip"])),
        "tax_amount": _normalize_number(_first_present(extracted_fields, ["tax_amount", "tax"])),
        "category": _first_present(extracted_fields, ["category", "expense_category"]),
        "payment_method": _first_present(extracted_fields, ["payment_method", "card_type", "payment_type"]),
        "receipt_id": _first_present(extracted_fields, ["receipt_id", "transaction_id", "id"]),
        "confidence": _normalize_number(_first_present(extracted_fields, ["confidence", "score"])),
    }
    return normalized


def normalize_with_openai(extracted_fields: Dict[str, Any]) -> Dict[str, Any]:
    response = client.responses.create(
        model="gpt-5.4-mini",
        input=[
            {
                "role": "system",
                "content": "Normalize extracted expense fields into the requested JSON schema exactly.",
            },
            {
                "role": "user",
                "content": json.dumps(extracted_fields),
            },
        ],
        text={
            "format": {
                "type": "json_schema",
                "name": "expense_normalization",
                "schema": STANDARD_SCHEMA,
                "strict": True,
            }
        },
    )
    return json.loads(response.output_text)


def main() -> None:
    import sys

    payload = json.loads(sys.stdin.read() or "{}")
    result = normalize_with_openai(payload) if os.environ.get("OPENAI_API_KEY") else normalize_expense(payload)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
